import{_ as o,a0 as a,w as r,s as I,ao as u,I as e,x as t,a1 as l,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"UNIGINE 可能是 Linux 上最好的遊戲引擎 | LCTT x X-CMD","titleTemplate":false,"description":"UNIGINE 可能是 Linux 上最好的遊戲引擎 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"UNIGINE 可能是 Linux 上最好的遊戲引擎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"UNIGINE 可能是 Linux 上最好的遊戲引擎 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/UNIGINE Is Probably the Best Gaming Engine on Linux","title":"UNIGINE 可能是 Linux 上最好的遊戲引擎","tag":"201312","desc":""},"relativePath":"201312/UNIGINE Is Probably the Best Gaming Engine on Linux.md","filePath":"[post].md"}'),p={name:"201312/UNIGINE Is Probably the Best Gaming Engine on Linux.md"};function N(m,n,g,d,x,G){const i=a("Link");return r(),I("div",null,[n[14]||(n[14]=u('<h1 id="unigine-可能是-linux-上最好的遊戲引擎" tabindex="-1">UNIGINE 可能是 Linux 上最好的遊戲引擎 <a class="header-anchor" href="#unigine-可能是-linux-上最好的遊戲引擎" aria-label="Permalink to “UNIGINE 可能是 Linux 上最好的遊戲引擎”">​</a></h1><p><strong>UNIGINE，是一個實時的 3D 引擎，它能夠在所有主流的平台上運行，包括 Linux，並剛剛升級到新的版本，帶給了我們一些重要的新特性。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484-2.jpg" alt=""></p><p>Unigine 引擎正是由 Unigine 公司開發的， 同時這公司還開發了 Heaven DX11 基準測試軟件。 這公司開發的技術總是越來越好，並且隨着他們最近在 Linux 平台上的擴展，我們真的很高興看到這引擎在最近時間作出的重大的更新。</p><p>在 UNIGINE 引擎最近作出的更新中，最大的更新是通用圖像生成器接口 (Common Image Generator Interface/CIGI) 協議。</p><p>據引擎的開發者説，這個接口在模擬行業中，是一種用於主機設備與圖像生成器 (IG) 之間通信的標準方法來的。</p><h3 id="新款-unigine-引擎的亮點" tabindex="-1">新款 UNIGINE 引擎的亮點 <a class="header-anchor" href="#新款-unigine-引擎的亮點" aria-label="Permalink to “新款 UNIGINE 引擎的亮點”">​</a></h3><ul><li>在笛卡爾座標系中增加了對 WGS84，ECF 和 NED 座標系的支持（這會幫助開發者更好地在用 Unigine 開發的項目中使用實時的 GIS 數據）；</li><li>實施了遊戲框架，這樣使得遊戲更加容易地創建，同時這種特性包括實體與節點的自動鏈接、層次與世界的自動鏈接、實體對象管理、貫穿所有層次的遊戲全局上下文、事件處理系統、最佳的實體更新等等。</li><li>增加渲染時幀率的穩定性。</li><li>兩個新的選項，2D 噪音和 3D 噪音（編輯器中的狀態選項卡），已被添加到 mesh_leaf_base 材質中。</li><li>一個新的參數，遮擋屏蔽，已經被添加到所有的材質中。</li><li>密雜草叢的高度現已實現同步。</li><li>修復了在渲染非 Flash 閃屏時崩潰的漏洞。</li></ul>',8)),e("p",null,[n[1]||(n[1]=t("所有平台的完整新特性列表，可以在官方的",-1)),l(i,{href:"http://www.unigine.com/devlog/2013/11/27/113"},{default:s(()=>[...n[0]||(n[0]=[t("公告",-1)])]),_:1}),n[2]||(n[2]=t("中找到。.",-1))]),n[15]||(n[15]=e("p",null,"要記住 UNIGINE 引擎只針對商業企業，並不向廣大用户提供試用版。",-1)),n[16]||(n[16]=e("hr",null,null,-1)),e("p",null,[n[4]||(n[4]=t("via: ",-1)),l(i,{href:"http://news.softpedia.com/news/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484.shtml"},{default:s(()=>[...n[3]||(n[3]=[t("http://news.softpedia.com/news/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484.shtml",-1)])]),_:1})]),e("p",null,[n[7]||(n[7]=t("譯者：",-1)),l(i,{href:"https://github.com/hyaocuk"},{default:s(()=>[...n[5]||(n[5]=[t("hyaocuk",-1)])]),_:1}),n[8]||(n[8]=t(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[11]||(n[11]=t("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原創翻譯，",-1)),l(i,{href:"http://linux.cn/"},{default:s(()=>[...n[10]||(n[10]=[t("Linux中國",-1)])]),_:1}),n[13]||(n[13]=t(" 榮譽推出",-1))])])}const T=o(p,[["render",N]]);export{L as __pageData,T as default};
